# Внутри разделов справочника заголовок примера ниже h2 раздела.
for page in PAGES:
    for field in ['live', 'anatomy_html', 'states']:
        page[field] = page[field].replace('<h2', '<h3').replace('</h2>', '</h3>')

# Нумерация связывает живую схему и список анатомии.
for page in PAGES:
    sample = page['anatomy_html']
    slots = {
      'page-header': [('dk-head__title', 1), ('dk-head__subtitle', 2), ('dk-head__actions', 3)],
      'widget-header': [('dk-widget__heading', 1), ('dk-widget__title', 2), ('dk-widget__meta', 3), ('dk-widget__actions', 4)],
      'widget': [('dk-widget dk-widget--overview', 1), ('dk-widget__head', 2), ('dk-widget__body', 3), ('dk-widget__footer', 4)]
    }[page['slug']]
    for name, number in slots:
        sample = sample.replace('class="'+name+'">', 'class="'+name+'"><b class="sc-callout">'+str(number)+'</b>', 1)
    if page['slug'] == 'widget':
        sample = '<div class="dk-grid"><div class="dk-col--full"><b class="sc-callout">5</b>'+sample+'</div></div>'
    page['anatomy_html'] = sample
